operation.add:
if (!class_exists('Mobile_Detect')) {
    require_once(DIR_SYSTEM . 'Mobile_Detect.php');
}

$wdh_mobile_detect = new Mobile_Detect;

if (!$wdh_mobile_detect->isTablet() && $wdh_mobile_detect->isMobile()) {
    $data['thumb'] = $this->model_tool_image->resizeWebp($product_info['image'], 480, 480);
} else {
    $data['thumb'] = $this->model_tool_image->resize(
        $product_info['image'],
        $this->config->get('theme_' . $this->config->get('config_theme') . '_image_thumb_width'),
        $this->config->get('theme_' . $this->config->get('config_theme') . '_image_thumb_height')
    );
}
